curl -X POST 'https://api.linkedin.com/rest/adAccounts/{adAccountId}/adCampaigns' \
-H 'Authorization: Bearer {INSERT_TOKEN}' \
-H 'Content-Type: application/json' \
-H 'Linkedin-Version: {version number in the format YYYYMM}' \ 
-H 'X-Restli-Protocol-Version: 2.0.0' 
--data '{
   //Standard request to create a campaign. See campaign documentation for full samples.
   "offsiteDeliveryEnabled":true,
   "offsitePreferences":{
      "iabCategories":{
         "exclude":[
            "urn:li:iabCategory:IAB5-3",
            "urn:li:iabCategory:IAB1-1"
         ]
      }
   }
}'

curl -X POST 'https://api.linkedin.com/rest/adAccounts/{adAccountId}/adCampaigns/{campaignId}' \
-H 'Authorization: Bearer {INSERT_TOKEN}' \
-H 'Content-Type: application/json' \
-H 'Linkedin-Version: {version number in the format YYYYMM}' \ 
-H 'X-Restli-Protocol-Version: 2.0.0' 
--data '{
    "patch": {
        "$set": {
            "offsiteDeliveryEnabled": true,
            "offsitePreferences": {
                "iabCategories": {
                    "exclude": [
                        "urn:li:iabCategory:IAB5-3",
                        "urn:li:iabCategory:IAB1-1"
                    ]
                }
            }
        }
    }
}'

curl -X POST 'https://api.linkedin.com/rest/adAccounts/{adAccountId}/adCampaigns/{campaignId}' \
-H 'Authorization: Bearer {INSERT_TOKEN}' \
-H 'Content-Type: application/json' \
-H 'Linkedin-Version: {version number in the format YYYYMM}' \ 
-H 'X-Restli-Protocol-Version: 2.0.0' 
--data '{
    "patch": {
        "$set": {
            "offsitePreferences": {
                "iabCategories": {
                    "exclude": []
                }
            }
        }
    }
}'

curl -X POST 'https://api.linkedin.com/rest/adPublisherRestrictions?action=generateRestrictionsDownloadUrl' \
-H 'Authorization: Bearer {INSERT_TOKEN}' \
-H 'Content-Type: application/json' \
-H 'Linkedin-Version: {version number in the format YYYYMM}' \ 
-H 'X-Restli-Protocol-Version: 2.0.0' 
--data '{
  "publisherRestrictionId": {id}
}'

curl -X PUT 'https://api.linkedin.com/rest/adAccountTrustPreferences/{sponsoredAccountId}' \
-H 'Authorization: Bearer {INSERT_TOKEN}' \
-H 'Content-Type: application/json' \
-H 'Linkedin-Version: {version number in the format YYYYMM}' \ 
-H 'X-Restli-Protocol-Version: 2.0.0' 
--data '{
    "offsiteAccountPreferences": {
        "publisherRestrictionFiles": {
            "include": [
                "urn:li:adPublisherFile:13"
            ],
            "exclude": [
                "urn:li:adPublisherFile:12"
            ]
        }
    }
}'
